<?php use VO\Support\Template; use VO\Cart\CartController; ob_start(); $pricing=$state['pricing']; $cart=$state['cart']; ?>
<p><a href="/carrito">← Volver al carrito</a></p><h1>Checkout</h1><?php if ($flash): ?><p class="notice"><?= Template::e($flash) ?></p><?php endif; ?><?php if (!empty($pricing['price_changed'])): ?><p class="warning">Los precios se actualizaron desde tu última revisión. Nuevo total: <?= Template::e(CartController::money((int)$pricing['grand_total_cents'])) ?></p><?php endif; ?>
<section class="card"><h2>Resumen del carrito</h2><ul><?php foreach ($state['details'] as $line): ?><li><?= Template::e($line['name']) ?> × <?= (int)$line['qty'] ?> — <?= Template::e(CartController::money((int)($line['pricing']['line_total_cents'] ?? 0))) ?></li><?php endforeach; ?></ul></section>
<form class="card checkout-form" method="post" action="/checkout-data"><h2>Datos de entrega y pago</h2><label>Entrega <select name="fulfillment" data-fulfillment><option value="pickup" <?= $cart['fulfillment']==='pickup'?'selected':'' ?>>Retiro</option><option value="delivery" <?= $cart['fulfillment']==='delivery'?'selected':'' ?>>Envío</option></select></label><label>Sucursal <select name="branch_id"><?php foreach ($branches as $b): ?><option value="<?= (int)$b['id'] ?>" <?= (int)($cart['branch_id'] ?? 0)===(int)$b['id']?'selected':'' ?>><?= Template::e($b['name']) ?></option><?php endforeach; ?></select></label><label>Pago <select name="payment_method"><option value="cash" <?= $cart['payment_method']==='cash'?'selected':'' ?>>Efectivo</option><option value="mercadopago" <?= $cart['payment_method']==='mercadopago'?'selected':'' ?>>Mercado Pago</option><option value="transfer" <?= $cart['payment_method']==='transfer'?'selected':'' ?>>Transferencia</option></select></label><div data-address-fields><label>Calle <input name="street" value="<?= Template::e($cart['address_json']['street'] ?? '') ?>"></label><label>Ciudad <input name="city" value="<?= Template::e($cart['address_json']['city'] ?? '') ?>"></label></div><label>Nombre <input name="name" data-customer-name></label><label>Teléfono <input name="phone" data-customer-phone></label><label>Email <input name="email" data-customer-email></label><label>Nota <textarea name="customer_note"><?= Template::e($cart['customer_note'] ?? '') ?></textarea></label><button>Actualizar vista previa</button></form>
<section class="card" data-preview data-confirm-storage="sessionStorage"><h2>Detalle de precios</h2><table data-confirm-breakdown><tr><th>Concepto</th><th>Importe</th></tr><tr><td>Ítems</td><td><?= Template::e(CartController::money((int)$pricing['gross_items_cents'])) ?></td></tr><tr><td>Promos</td><td>- <?= Template::e(CartController::money((int)(($pricing['item_promotions_cents'] ?? 0)+($pricing['order_promotions_cents'] ?? 0)))) ?></td></tr><tr><td>Cupón</td><td>- <?= Template::e(CartController::money((int)($pricing['coupon_discount_cents'] ?? 0))) ?></td></tr><tr><td>Descuento por pago</td><td>- <?= Template::e(CartController::money((int)($pricing['payment_discount_cents'] ?? 0))) ?></td></tr><tr><td>Envío</td><td><?= Template::e(CartController::money((int)($pricing['delivery_fee_cents'] ?? 0))) ?></td></tr><tr><th>Total</th><th><?= Template::e(CartController::money((int)$pricing['grand_total_cents'])) ?></th></tr></table><p class="warning" data-confirm-message hidden></p><button data-confirm-order data-accepted-totals='<?= Template::e(json_encode(['accepted_grand_total_cents'=>(int)$pricing['grand_total_cents'],'accepted_lines'=>array_map(fn($l)=>['line_total_cents'=>(int)$l['line_total_cents']], $pricing['lines'] ?? [])], JSON_UNESCAPED_SLASHES)) ?>' data-confirm-url="/api/cart/confirm" <?= !empty($pricing['price_changed'])?'disabled':'' ?>>Confirmar pedido</button></section>
<script src="/assets/js/shop/cart.js" defer></script><?php $content = ob_get_clean(); require dirname(__DIR__, 2) . '/Catalog/templates/layout.php'; ?>
